using System;
using System.Data;
using System.Data.OleDb;
namespace TutAcadSupport {
internal static class School {
 public static DataTable Courses(){return Db.Query("SELECT CourseCode,CourseName FROM Course ORDER BY CourseName");}
 public static DataTable Tutors(){return Db.Query("SELECT TutorID,FirstName & ' ' & LastName AS TutorName,ContactInformation,AcademicAverage,TutoringMode FROM Tutor ORDER BY LastName");}
 static string SessionSql="SELECT s.SessionID,s.RequestID,r.CourseCode,s.StudentNumber,s.TutorID,s.StartTime,s.EndTime,s.[Mode],s.AttendanceStatus,s.TopicsCovered,s.Feedback FROM TutoringSession AS s INNER JOIN TutoringRequest AS r ON s.RequestID=r.RequestID";
 public static DataTable Sessions(){Auth.Need("Student","Tutor","Administrator");string filter=Auth.Role=="Student"?" WHERE s.StudentNumber=?":Auth.Role=="Tutor"?" WHERE s.TutorID=?":"";return filter.Length==0?Db.Query(SessionSql+" ORDER BY s.StartTime DESC"):Db.Query(SessionSql+filter+" ORDER BY s.StartTime DESC",Auth.PersonID);}
 public static DataTable Requests(){Auth.Need("Student","Administrator");string q="SELECT RequestID,StudentNumber,CourseCode,SupportType,Availability,[Status],SubmissionDate,MatchedTutorID FROM TutoringRequest";return Auth.Role=="Student"?Db.Query(q+" WHERE StudentNumber=? ORDER BY SubmissionDate DESC",Auth.PersonID):Db.Query(q+" ORDER BY SubmissionDate DESC");}
 public static DataTable FindTutors(string course,DateTime start,DateTime end){Auth.Need("Student","Administrator");Rules.Period(start,end,DateTime.Now);var d=Db.Query("SELECT t.TutorID,t.FirstName & ' ' & t.LastName AS TutorName,t.TutoringMode FROM Tutor AS t INNER JOIN TutorQualification AS q ON t.TutorID=q.TutorID WHERE q.CourseCode=?",course);var result=d.Clone();foreach(DataRow r in d.Rows){string tutor=r[0].ToString();if(Db.Query("SELECT AvailabilityID FROM TutorAvailability WHERE TutorID=? AND StartAt<=? AND EndAt>=?",tutor,start,end).Rows.Count==0)continue;if(Db.Query("SELECT SessionID FROM TutoringSession WHERE TutorID=? AND AttendanceStatus<>? AND StartTime<? AND EndTime>?",tutor,"Cancelled",end,start).Rows.Count>0)continue;result.ImportRow(r);}return result;}
 static void Check(OleDbConnection c,OleDbTransaction t,string student,string tutor,string course,DateTime start,DateTime end,string excluded){
  Rules.Period(start,end,DateTime.Now);
  Rules.Require(Db.Query(c,t,"SELECT TutorID FROM TutorQualification WHERE TutorID=? AND CourseCode=?",tutor,course).Rows.Count==1,"Tutor is not qualified for this course.");
  Rules.Require(Db.Query(c,t,"SELECT AvailabilityID FROM TutorAvailability WHERE TutorID=? AND StartAt<=? AND EndAt>=?",tutor,start,end).Rows.Count>0,"Tutor is unavailable for the full period. Search availability again.");
  Rules.Require(Db.Query(c,t,"SELECT SessionID FROM TutoringSession WHERE AttendanceStatus<>? AND SessionID<>? AND StartTime<? AND EndTime>? AND (TutorID=? OR StudentNumber=?)","Cancelled",excluded,end,start,tutor,student).Rows.Count==0,"The student or tutor has an overlapping session. Choose another time.");
 }
 public static string SubmitRequest(string course,string support,string availability){Auth.Need("Student");Rules.Text(availability,"Availability",255);using(var c=Db.Open())using(var t=c.BeginTransaction()){string id=CreateRequest(c,t,Auth.PersonID,course,support,availability,"Submitted",null);t.Commit();return id;}}
 static string CreateRequest(OleDbConnection c,OleDbTransaction t,string student,string course,string support,string availability,string status,string tutor){
  Rules.Require(Array.IndexOf(new[]{"Content clarification","Exam preparation","Assignment assistance","Study skills"},support)>=0,"Select a valid support type.");Rules.Require(Db.Query(c,t,"SELECT CourseCode FROM Course WHERE CourseCode=?",course).Rows.Count==1,"Select a valid course.");
  string id=Db.Id("REQ");var profile=Db.Query(c,t,"SELECT AcademicRiskLevel FROM Student WHERE StudentNumber=?",student);Rules.Require(profile.Rows.Count==1,"Student not found.");
  Db.Exec(c,t,"INSERT INTO TutoringRequest (RequestID,StudentNumber,CourseCode,MatchedTutorID,SupportType,PriorityLevel,Availability,[Status],SubmissionDate) VALUES (?,?,?,?,?,?,?,?,?)",id,student,course,tutor,support,profile.Rows[0][0],availability,status,DateTime.Now);return id;
 }
 public static string Book(string course,string tutor,string support,DateTime start,DateTime end){Auth.Need("Student");using(var c=Db.Open())using(var t=c.BeginTransaction()){Check(c,t,Auth.PersonID,tutor,course,start,end,"");string req=CreateRequest(c,t,Auth.PersonID,course,support,start.ToString("g")+" - "+end.ToString("t"),"Scheduled",tutor);string id=InsertSession(c,t,req,Auth.PersonID,tutor,start,end);t.Commit();return id;}}
 static string InsertSession(OleDbConnection c,OleDbTransaction t,string req,string student,string tutor,DateTime start,DateTime end){string id=Db.Id("SES");string mode=Db.Query(c,t,"SELECT TutoringMode FROM Tutor WHERE TutorID=?",tutor).Rows[0][0].ToString();Db.Exec(c,t,"INSERT INTO TutoringSession (SessionID,RequestID,StudentNumber,TutorID,SessionDate,StartTime,EndTime,[Mode],AttendanceStatus) VALUES (?,?,?,?,?,?,?,?,?)",id,req,student,tutor,start.Date,start,end,mode,"Scheduled");return id;}
 public static void Change(string session,DateTime start,DateTime end,bool cancel){Auth.Need("Student");using(var c=Db.Open())using(var t=c.BeginTransaction()){
  var d=Db.Query(c,t,SessionSql+" WHERE s.SessionID=? AND s.StudentNumber=?",session,Auth.PersonID);Rules.Require(d.Rows.Count==1,"Select your booking.");var r=d.Rows[0];Rules.ChangeAllowed(r["AttendanceStatus"].ToString(),(DateTime)r["StartTime"],DateTime.Now);
  if(cancel){Db.Exec(c,t,"UPDATE TutoringSession SET AttendanceStatus=? WHERE SessionID=?","Cancelled",session);Db.Exec(c,t,"UPDATE TutoringRequest SET [Status]=? WHERE RequestID=?","Cancelled",r["RequestID"]);}else{Check(c,t,Auth.PersonID,r["TutorID"].ToString(),r["CourseCode"].ToString(),start,end,session);Db.Exec(c,t,"UPDATE TutoringSession SET SessionDate=?,StartTime=?,EndTime=? WHERE SessionID=?",start.Date,start,end,session);Db.Exec(c,t,"UPDATE TutoringRequest SET Availability=? WHERE RequestID=?",start.ToString("g")+" - "+end.ToString("t"),r["RequestID"]);}t.Commit();
 }}
 public static void Feedback(string session,double score){Auth.Need("Student");Rules.Require(score>=0&&score<=10,"Rating must be between 0 and 10.");using(var c=Db.Open())Rules.Require(Db.Exec(c,null,"UPDATE TutoringSession SET Feedback=? WHERE SessionID=? AND StudentNumber=? AND AttendanceStatus=?",score,session,Auth.PersonID,"Completed")==1,"Select one of your completed sessions to rate.");}
 public static void Complete(string session,string status,string topics){Auth.Need("Administrator","Tutor");Rules.Require(status=="Completed"||status=="Absent","Choose Completed or Absent.");Rules.Text(topics,"Topics / notes",255);using(var c=Db.Open())using(var t=c.BeginTransaction()){
  var d=Db.Query(c,t,"SELECT * FROM TutoringSession WHERE SessionID=?",session);Rules.Require(d.Rows.Count==1,"Select a session.");var r=d.Rows[0];Rules.Require(Auth.Role=="Administrator"||r["TutorID"].ToString()==Auth.PersonID,"This is another tutor's session.");Rules.Require(r["AttendanceStatus"].ToString()=="Scheduled","Only scheduled sessions can be marked.");Rules.Require((DateTime)r["EndTime"]<=DateTime.Now,"Wait until the session ends before recording attendance.");
  Db.Exec(c,t,"UPDATE TutoringSession SET AttendanceStatus=?,TopicsCovered=? WHERE SessionID=?",status,topics.Trim(),session);Db.Exec(c,t,"UPDATE TutoringRequest SET [Status]=? WHERE RequestID=?",status,r["RequestID"]);t.Commit();
 }}
 public static void Match(string request,string tutor,DateTime start,DateTime end){Auth.Need("Administrator");using(var c=Db.Open())using(var t=c.BeginTransaction()){
  var d=Db.Query(c,t,"SELECT * FROM TutoringRequest WHERE RequestID=?",request);Rules.Require(d.Rows.Count==1,"Select a request.");var r=d.Rows[0];Rules.Require(r["Status"].ToString()=="Submitted","Only submitted requests can be matched.");Check(c,t,r["StudentNumber"].ToString(),tutor,r["CourseCode"].ToString(),start,end,"");InsertSession(c,t,request,r["StudentNumber"].ToString(),tutor,start,end);Db.Exec(c,t,"UPDATE TutoringRequest SET MatchedTutorID=?,VerifiedByAdminID=?,[Status]=? WHERE RequestID=?",tutor,Auth.PersonID,"Scheduled",request);t.Commit();
 }}
 public static void AvailabilityAccess(string tutor){Auth.Need("Administrator","Tutor");Rules.Require(Auth.Role=="Administrator"||Auth.PersonID==tutor,"You may manage only your own availability.");}
 public static DataTable Availability(string tutor){AvailabilityAccess(tutor);return Db.Query("SELECT AvailabilityID,StartAt,EndAt FROM TutorAvailability WHERE TutorID=? ORDER BY StartAt",tutor);}
 public static void SaveAvailability(string tutor,int id,DateTime start,DateTime end,bool delete){AvailabilityAccess(tutor);if(!delete)Rules.Period(start,end,DateTime.Now);using(var c=Db.Open())using(var t=c.BeginTransaction()){
  if(id>0){var d=Db.Query(c,t,"SELECT * FROM TutorAvailability WHERE AvailabilityID=? AND TutorID=?",id,tutor);Rules.Require(d.Rows.Count==1,"Select an availability period.");var r=d.Rows[0];var sessions=Db.Query(c,t,"SELECT StartTime,EndTime FROM TutoringSession WHERE TutorID=? AND AttendanceStatus=? AND StartTime<? AND EndTime>?",tutor,"Scheduled",r["EndAt"],r["StartAt"]);foreach(DataRow s in sessions.Rows)Rules.Require(!delete && start<=(DateTime)s[0] && end>=(DateTime)s[1],"This change would remove availability needed by a scheduled booking.");}
  if(delete)Db.Exec(c,t,"DELETE FROM TutorAvailability WHERE AvailabilityID=? AND TutorID=?",id,tutor);
  else {Rules.Require(Db.Query(c,t,"SELECT AvailabilityID FROM TutorAvailability WHERE TutorID=? AND AvailabilityID<>? AND StartAt<? AND EndAt>?",tutor,id,end,start).Rows.Count==0,"This period overlaps existing availability.");if(id==0)Db.Exec(c,t,"INSERT INTO TutorAvailability (TutorID,StartAt,EndAt) VALUES (?,?,?)",tutor,start,end);else Db.Exec(c,t,"UPDATE TutorAvailability SET StartAt=?,EndAt=? WHERE AvailabilityID=? AND TutorID=?",start,end,id,tutor);}t.Commit();
 }}
 public static string SaveTutor(string id,string first,string last,string contact,double average,string mode,string username,string password){Auth.Need("Administrator");Rules.PersonName(first,"First name");Rules.PersonName(last,"Last name");Rules.Contact(contact);Rules.Require(average>=0&&average<=100,"Average must be between 0 and 100.");Rules.Require(mode=="Online"||mode=="In-person","Select a tutoring mode.");bool create=String.IsNullOrEmpty(id);string[] hash=null;if(create){Rules.Text(username,"Username",50);Rules.Password(password);hash=Rules.Hash(password);id=Db.Id("TUT",10);}
  using(var c=Db.Open())using(var t=c.BeginTransaction()){
   Rules.Require(Db.Query(c,t,"SELECT TutorID FROM Tutor WHERE ContactInformation=? AND TutorID<>?",contact.Trim(),id).Rows.Count==0,"Another tutor uses this contact information.");
   if(create){Rules.Require(Db.Query(c,t,"SELECT Username FROM AppUser WHERE Username=?",username.Trim()).Rows.Count==0,"Username is already in use.");Db.Exec(c,t,"INSERT INTO Tutor (TutorID,FirstName,LastName,ContactInformation,AcademicAverage,TutoringMode) VALUES (?,?,?,?,?,?)",id,first.Trim(),last.Trim(),contact.Trim(),average,mode);Db.Exec(c,t,"INSERT INTO AppUser (Username,PasswordHash,PasswordSalt,UserRole,PersonID,IsActive) VALUES (?,?,?,?,?,?)",username.Trim(),hash[1],hash[0],"Tutor",id,true);Db.Exec(c,t,"INSERT INTO TutorAdmin (TutorID,AdminID) VALUES (?,?)",id,Auth.PersonID);}
   else Rules.Require(Db.Exec(c,t,"UPDATE Tutor SET FirstName=?,LastName=?,ContactInformation=?,AcademicAverage=?,TutoringMode=? WHERE TutorID=?",first.Trim(),last.Trim(),contact.Trim(),average,mode,id)==1,"Tutor no longer exists.");t.Commit();return id;
  }
 }
 public static void Qualify(string tutor,string course){Auth.Need("Administrator");Rules.Require(Db.Query("SELECT TutorID FROM Tutor WHERE TutorID=?",tutor).Rows.Count==1,"Select an existing tutor.");Rules.Require(Db.Query("SELECT CourseCode FROM Course WHERE CourseCode=?",course).Rows.Count==1,"Select a valid course.");Rules.Require(Db.Query("SELECT TutorID FROM TutorQualification WHERE TutorID=? AND CourseCode=?",tutor,course).Rows.Count==0,"Tutor already has that qualification.");Db.Exec("INSERT INTO TutorQualification (TutorID,CourseCode,VerifiedByAdminID,VerificationDate) VALUES (?,?,?,?)",tutor,course,Auth.PersonID,DateTime.Now);}
}
}
